		@Override
		public CloseableIteration<? extends Resource> getContextIDs() {
			contextRequests++;
			return contexts;
		}

		@Override
		public Function<Value, Value> getValueCapturer() {
			return value -> {
				Resource owned = VF.createIRI(value.stringValue());
				captured.add(owned);
				return owned;
			};
		}

