	private static final class ProbeIteration<E> implements CloseableIteration<E> {
		private final Iterator<E> iterator;
		private int reads;
		private int closes;
		private RuntimeException readFailure;
		private RuntimeException closeFailure;

		private ProbeIteration(List<E> values) {
			iterator = values.iterator();
		}

		@Override
		public boolean hasNext() {
			if (readFailure != null) {
				throw readFailure;
			}
			return iterator.hasNext();
		}

		@Override
		public E next() {
			reads++;
			return iterator.next();
		}

		@Override
		public void close() {
			if (closes == 0) {
				closes++;
				if (closeFailure != null) {
					throw closeFailure;
				}
			}
		}
	}
